/* Cyberpunk defense-grid interface */
:root{--ink:#dcecff;--muted:#8ca9bf;--cream:#101a2b;--paper:#142238;--gold:#ffdf68;--green:#00e6c3;--navy:#101a2b;--line:#29415a;--pink:#ff4fc8;--blue:#36d9ff}
html{background:#080e19}
body{color:var(--ink);background:radial-gradient(ellipse at 50% 0%,#1d3150 0,#101a2b 62%,#080e19 100%)}
.game-shell{background:linear-gradient(180deg,#121f33 0%,#101a2b 100%);box-shadow:0 0 70px #00d9ff16}
.brand-mark{background:#13253b;color:#ffe66d;box-shadow:0 0 17px #00eaff35,inset 0 0 0 1px #00eaff55}
