.wave-progress>span,.enemy-count{color:#9bc3d4}
.progress-track,.xp-track{background:#253951}.progress-track i{background:linear-gradient(90deg,#ff42c9,#ffdc61)}
.canvas-frame{box-shadow:inset 0 0 0 1px #8cf7ff33,0 0 24px #00eaff14}
.float-hint{background:#101b2cdd;border:1px solid #5aeaff66;color:#c5f8ff}
.banner{text-shadow:0 0 5px #00eaff,0 0 18px #ff42c9,0 2px 0 #152138}
