.xp-row{color:#91b5c5}.xp-row>b{color:#b4d7e3}.xp-track i{background:linear-gradient(90deg,#00e6c3,#36d9ff,#ff4fc8)}
.outfit-chip b,.buff-chip b{color:#d8f1fa}.buff-chip>span{color:#ffe66d}
