footer{color:#7899ab}footer span{color:#ff4fc8}
.modal-backdrop{background:#050a14cc}.modal-card,.end-card{background:#16263b;color:#e5f6ff;border:1px solid #35516b;box-shadow:0 14px 60px #0009}.modal-card>p,.end-card p:not(.eyebrow){color:#9bb8c8}.modal-close{background:#263a50;color:#b9dbe8}.outfit-option{background:#101d30;border-color:#2a4359}.outfit-option.selected{background:#14343a;border-color:#00d9c0}.outfit-detail b{color:#e5faff}.outfit-detail small{color:#91b3c2}.outfit-state{background:#087e75;color:#eafffb}.outfit-state.locked{background:#28384a;color:#91a5b1}.pause-card .pause-icon{background:#183b49;color:#5ce8d8}.pause-card .primary-btn,.primary-btn{background:#087e86;color:#efffff;box-shadow:0 4px 0 #07555e}
