+.wave-progress>span,.enemy-count{color:#9bc3d4}
+.progress-track,.xp-track{background:#253951}.progress-track i{background:linear-gradient(90deg,#ff42c9,#ffdc61)}
+.canvas-frame{box-shadow:inset 0 0 0 1px #8cf7ff33,0 0 24px #00eaff14}
+.float-hint{background:#101b2cdd;border:1px solid #5aeaff66;color:#c5f8ff}
+.banner{text-shadow:0 0 5px #00eaff,0 0 18px #ff42c9,0 2px 0 #152138}
+.arena-caption{color:#80a5b7}.arena-caption span:last-child{color:#aac9d8}
+.sun-dot{box-shadow:0 0 9px currentColor}
+.level-tag{background:#183b49;color:#61f2df}
+.wardrobe-btn{background:#302547;color:#ff80d7;box-shadow:0 2px 0 #1b142b}.wardrobe-btn span{color:#ffe66d}
+.xp-row{color:#91b5c5}.xp-row>b{color:#b4d7e3}.xp-track i{background:linear-gradient(90deg,#00e6c3,#36d9ff,#ff4fc8)}
+.outfit-chip b,.buff-chip b{color:#d8f1fa}.buff-chip>span{color:#ffe66d}
+.upgrade-btn{background:#087e86;color:#e9ffff;box-shadow:0 3px 0 #07555e}.upgrade-btn small{color:#a7ffff}
+.controls-label>span:last-child{color:#8eafbe}
+.skill-row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}
+.skill-btn{gap:5px;padding:6px 5px;background:#102b38;color:#dbfaff;border-color:#28616c;box-shadow:0 3px 0 #0c202a}
+.skill-btn.storm{background:#30243c;border-color:#74416e;box-shadow:0 3px 0 #201629}
+.skill-btn.helper{background:#132e35;border-color:#287c74;box-shadow:0 3px 0 #0b211f}
+.skill-art{width:26px;height:27px;background:#16414a;color:#5df4e6;font-size:17px}
+.storm .skill-art{background:#503450;color:#ff83d8;font-size:19px}
+.helper .skill-art{background:#16413e;color:#73ffcf;font-size:17px}
+.skill-text b{font-size:7px;letter-spacing:.25px}.skill-text small{font-size:6.5px;color:#91b3c2}
